s=s.replace("const [draft,setDraft]", "const [formTab,setFormTab]=useState('기본 정보');\n const [draft,setDraft]")
s=s.replace("setTab('병원 화면·서비스');}","setTab('병원 화면·서비스');setFormTab('기본 정보');}")
start=s.index(' const form=')
end=s.index(' return <section',start)
s=s[:start]+''' const asset=(key:'photo'|'logo',title:string)=><div className={styles.asset}><div className={styles.assetImage}>{model[key]?<img src={model[key]} alt={title}/>:key==='photo'?<UserRound size={32}/>:<Building2 size={32}/>}</div><div className={styles.assetBody}><strong>{title}</strong><p>PNG · JPG · WebP / 150KB 이하</p><label className={styles.assetUpload}><ImagePlus size={15}/>이미지 선택<input aria-label={title+' 파일'} type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>void image(key,e.target.files?.[0])}/></label>{model[key]&&<button className={styles.textButton} onClick={()=>change(key,'')}>제거</button>}<details><summary>이미지 주소로 등록</summary><input aria-label={title+' 주소'} placeholder="https://" value={model[key].startsWith('data:')?'':model[key]} onChange={e=>change(key,e.target.value)}/></details></div></div>;
 const form=<><nav className={styles.formTabs} aria-label="병원 설정 항목">{['기본 정보','제공 서비스','소재 연결'].map(t=><button key={t} aria-pressed={formTab===t} onClick={()=>setFormTab(t)}>{t}{t==='제공 서비스'&&<span>{model.services.length}/5</span>}{t==='소재 연결'&&<span>{model.materials.length}</span>}</button>)}</nav>
 <div className={styles.formContent}>
 {formTab==='기본 정보'&&<><div className={styles.sectionIntro}><h3>이 병원의 화면을 준비하세요</h3><p>원장님과 병원 정보를 환자·직원 화면에 함께 적용합니다.</p></div><div className={styles.form}>
 <label>진료과<select aria-label="진료과" value={model.department} onChange={e=>setDraft({...model,department:e.target.value,materials:[]})}><option value="">진료과를 선택해 주세요</option>{DEPARTMENTS.map(d=><option key={d}>{d}</option>)}</select></label>
 <label>원장님 이름<input value={model.director} maxLength={100} placeholder="원장님 성함" onChange={e=>change('director',e.target.value)}/></label>
 <div className={styles.wide}><label>병원 대표 색상</label><div className={styles.colorField}><input aria-label="대표 색상" type="color" value={model.color} onChange={e=>change('color',e.target.value)}/><b>{model.color.toUpperCase()}</b><span>병원 로고와 어울리는 색상을 선택하세요.</span></div></div>
 </div><div className={styles.assetGrid}>{asset('logo','병원 로고')}{asset('photo','원장님 사진')}</div>
 <details className={styles.memo}><summary><FileText size={16}/>병원 요청·참고 메모{model.notes&&<span>작성됨</span>}</summary><textarea aria-label="병원 요청·참고 메모" rows={3} value={model.notes} onChange={e=>change('notes',e.target.value)} placeholder="병원에서 요청한 내용이나 참고 사항을 남기세요."/></details>
 <div className={styles.nextRow}><span>다음으로 이 병원이 제공할 서비스를 선택하세요.</span><button onClick={()=>setFormTab('제공 서비스')}>제공 서비스<ChevronRight size={16}/></button></div></>}
 {formTab==='제공 서비스'&&<><div className={styles.sectionIntro}><h3>제공할 서비스를 선택하세요</h3><p>선택한 서비스만 병원 직원용 페이지에 표시됩니다.</p></div><div className={styles.serviceList}>{HOSPITAL_SERVICES.map((name,i)=><label className={styles.serviceChoice} data-selected={model.services.includes(name)} key={name}><input type="checkbox" checked={model.services.includes(name)} onChange={e=>change('services',e.target.checked?[...model.services,name]:model.services.filter(v=>v!==name))}/><span><b>{name}</b><small>{['오래 방문하지 않은 환자의 재방문 안내','예약 일정에 맞춘 방문 안내','진료 후 주의사항과 생활 관리 안내','상담 이후 확인과 후속 안내','검사 결과에 따른 확인·안내'][i]}</small></span><span className={styles.checkMark}><Check size={16}/></span></label>)}</div>{section==='세팅'&&preparation(1)}<div className={styles.nextRow}><span>선택한 서비스에 사용할 소재를 연결하세요.</span><button onClick={()=>setFormTab('소재 연결')}>소재 연결<ChevronRight size={16}/></button></div></>}
 {formTab==='소재 연결'&&<><div className={styles.sectionIntro}><h3>진료과 소재를 연결하세요</h3><p>{model.department||'진료과 미지정'} · 선택한 소재 {model.materials.length}개</p></div>{model.department==='재활의학과'?<><div className={styles.libraryBar}><span>연세리셀 소재 <b>99개</b></span><small>의료진 검수 전 원고</small></div><div className={styles.searchField}><Search size={17}/><input aria-label="소재 검색" value={materialSearch} placeholder="소재 이름 또는 코드 검색" onChange={e=>setMaterialSearch(e.target.value)}/></div><div className={styles.materials}>{catalog.materials.filter(m=>(m.id+m.name).includes(materialSearch)).map(m=><label key={m.id} className={styles.materialRow}><input type="checkbox" checked={model.materials.includes(m.id)} onChange={e=>change('materials',e.target.checked?[...model.materials,m.id]:model.materials.filter(v=>v!==m.id))}/><b>{m.name}</b><span>{m.id}</span></label>)}</div></>:<div className={styles.empty}><FileText size={28}/><h3>아직 연결할 소재가 없어요</h3><p>{model.department?'이 진료과의 공통 소재가 등록되면 여기에서 선택할 수 있습니다.':'기본 정보에서 진료과를 먼저 선택해 주세요.'}</p></div>}</>}
 </div></>;
''' + s[end:]
start=s.index(' return <section',s.index(' const asset='))
s=s[:start]+''' return <section className={styles.root} data-hospital-portal data-dirty={!!draft}>
 <header className={styles.pageHeader}><div><h2>{section==='세팅'?'병원 세팅':section==='운영'?'병원 운영':section}</h2><p>{section==='세팅'?'병원별 화면과 서비스를 준비하고, 운영을 시작하세요.':section==='운영'?'세팅이 끝난 병원의 자료와 서비스를 관리하세요.':'병원 정보와 적용할 화면을 한곳에서 관리하세요.'}</p></div><div className={styles.headerActions}>{draft&&<span className={styles.unsaved}>저장하지 않은 변경</span>}{section!=='운영'&&section!=='공통 양식'&&hospital&&<><Button variant="outline" disabled={busy} onClick={()=>void save('save')}><Save size={15}/>초안 저장</Button><Button className={styles.confirmButton} disabled={busy} onClick={()=>void save('confirm')}>세팅 확정<ArrowUpRight size={15}/></Button></>}</div></header>
 {error&&<p role="alert" className={styles.error}>{error}</p>}{notice&&<p role="status" className={styles.success}>{notice}</p>}
 {!loaded?<div className={styles.empty}><p>병원 정보를 불러오는 중입니다.</p><Button variant="outline" onClick={()=>void load().catch(e=>setError(e.message))}>다시 확인</Button></div>:<>
 <div className={styles.layout}><nav className={styles.hospitals} aria-label="병원 목록"><div className={styles.directoryHeader}><b>병원 목록</b><span>{visible.length}</span></div><div className={styles.searchField}><Search size={16}/><input aria-label="병원 검색" value={search} placeholder="병원 검색" onChange={e=>{if(draft)return;setSearch(e.target.value)}} disabled={!!draft}/></div>
 <div className={styles.directoryList}>{(section==='운영'?[{name:'세팅 완료 병원',items:completed}]:[{name:'세팅 진행 병원',items:pending},{name:'세팅 완료 병원',items:completed}]).map(group=><section key={group.name}><h3>{group.name}<span>{group.items.length}</span></h3>{group.items.filter(h=>shown.includes(h)).map(h=><button key={h.id} aria-current={hospital?.id===h.id?'page':undefined} onClick={()=>select(h.id)}><Building2 size={17}/><span><b>{h.name||h.alias}</b><small>{h.category}</small></span><ChevronRight size={14}/></button>)}{!group.items.length&&<p className={styles.groupEmpty}>확정된 병원 없음</p>}</section>)}</div></nav>
 <article className={styles.hospitalMain}>{!hospital?<div className={styles.empty}><Building2 size={30}/><h3>{section==='운영'?'운영할 병원을 준비해 주세요':'병원을 선택해 주세요'}</h3><p>{section==='운영'?'세팅을 확정한 병원이 이곳에 표시됩니다.':'병원 목록에서 설정할 병원을 선택하세요.'}</p></div>:<>
 <header className={styles.hospitalHeader}><div className={styles.hospitalAvatar}>{model.logo?<img src={model.logo} alt="병원 로고"/>:<Building2 size={25}/>}</div><div><h2>{hospital.name||hospital.alias}</h2><p>{hospital.category}<span>·</span>{model.department||'진료과 미지정'}</p></div><span className={confirmed?styles.confirmedBadge:styles.pendingBadge}>{confirmed?<Check size={13}/>:<Clock3 size={13}/>} {confirmed?'세팅 확정':'준비 중'}</span></header>
 {section==='세팅'&&<nav className={styles.stageTabs} aria-label="세팅 단계">{['이지행정','병원 화면·서비스','최초 EMR 업로드','화면 미리보기'].map((t,i)=><button key={t} aria-pressed={tab===t} onClick={()=>setTab(t)}><span>{i===3?'확인':i+1}</span>{t}</button>)}</nav>}
 <div className={styles.content}><div className={styles.editor}>
 {section==='병원 정보'&&<dl className={styles.metadata}>{[['담당자',hospital.reference?.contact],['계약',hospital.reference?.contracted],['EMR 업체',hospital.reference?.vendor],['사용 EMR',hospital.reference?.emr],['계약 범위',hospital.reference?.service]].map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value||'미등록'}</dd></div>)}</dl>}
 {(section==='병원 정보'||section==='세팅'&&tab==='병원 화면·서비스')&&form}
 {section==='세팅'&&tab==='이지행정'&&<div className={styles.formContent}>{preparation(0)}</div>}
 {section==='세팅'&&tab==='최초 EMR 업로드'&&<div className={styles.formContent}>{preparation(2)}</div>}
 {section==='운영'&&<div className={styles.formContent}><h3>반복 EMR 업로드</h3>{uploadSection}<section className={styles.section}><h3>적용 서비스</h3>{confirmed?.services.map(s=><p key={s}>{s}</p>)}</section></div>}
 {(section==='운영'||section==='세팅'&&tab==='화면 미리보기')&&<div className={styles.previewStage}><div className={styles.previewToolbar}><div><h3>병원 화면 미리보기</h3><p>입력한 정보와 선택한 서비스의 적용 모습을 확인하세요.</p></div><nav className={styles.tabs} aria-label="화면 미리보기"><button aria-pressed={screen==='patient'} onClick={()=>setScreen('patient')}>통합 환자 화면</button><button aria-pressed={screen==='staff'} onClick={()=>setScreen('staff')}>병원 직원용 페이지</button></nav></div><HospitalScreenPreview name={hospital.name||hospital.alias} profile={section==='운영'&&confirmed?confirmed:model} mode={screen} confirmed={section==='운영'}/><p className={styles.previewFootnote}>내부 검수용 미리보기 · 환자 정보·실제 발송 미연결</p></div>}
 {draft&&<div className={styles.draftFooter}><span>변경 내용을 초안으로 저장할 수 있습니다.</span><button className={styles.textButton} onClick={()=>setDraft(null)}>변경 취소</button></div>}
 {confirmed&&<p className={styles.formContent}><a target="_blank" rel="noreferrer" href={'/v2/hospitals/'+hospital.id+'/patient'}>확정 환자 화면<ArrowUpRight size={13}/></a> · <a target="_blank" rel="noreferrer" href={'/v2/hospitals/'+hospital.id+'/staff'}>확정 직원 화면<ArrowUpRight size={13}/></a></p>}
 {section==='세팅'&&<details className={styles.legacy}><summary>기존 세팅 기록·원격 설치 정보</summary><SSSetupJourney key={hospital.id} hospitals={hospitals} state={state} focus={{clinic:String(hospital.id)}} onSave={onSave} onTask={onTask} onNewTask={onNewTask}/></details>}
 </div><aside className={styles.rail}><div className={styles.railHeading}><h3>준비 진행</h3><span>{model.steps.filter(s=>s.complete).length}/3 완료</span></div><ol className={styles.progressList}>{model.steps.map((s,i)=><li key={s.name}><span className={s.complete?styles.stepDone:styles.stepPending}>{s.complete?<Check size={14}/>:i+1}</span><div><b>{s.name}</b><small>{s.complete?'완료 확인':'준비 중'}</small>{s.evidence&&<p>{s.evidence}</p>}</div></li>)}</ol>
 <div className={styles.selectionSummary}><p><span>제공 서비스</span><b>{model.services.length}<small> / 5</small></b></p><p><span>연결 소재</span><b>{model.materials.length}<small>개</small></b></p></div>
 {section==='세팅'&&tab!=='화면 미리보기'&&<button className={styles.previewLink} onClick={()=>setTab('화면 미리보기')}>화면 미리보기<ArrowUpRight size={15}/></button>}
 <details className={styles.railDetails}><summary>참고 자료</summary><p>{model.notes||'등록된 참고 메모가 없습니다.'}</p></details><details className={styles.railDetails}><summary>완료·변경 이력 <span>{saved?.history?.length||0}</span></summary>{saved?.history?.length?<ol>{[...saved.history].reverse().map((h,i)=><li key={i}><b>{h.action}</b><small>{new Date(h.at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}</small><small>{h.actor} · {h.steps.join(' · ')||'완료 항목 없음'}</small></li>)}</ol>:<p>아직 저장한 이력이 없습니다.</p>}</details></aside></div></>}</article></div>
 {section==='운영'&&<details className={styles.legacy}><summary>기존 운영 기록 확인</summary><p className={styles.notice}>기존 운영 이력은 유지합니다. 버전 2 세팅 확정 상태와는 별도입니다.</p><ServiceCenter hospitals={hospitals} state={state} onTask={onTask} onNewTask={onNewTask} onSave={onSave} onNavigate={onNavigate} focus={focus}/></details>}
 </>}
 </section>;
}
'''
p.write_text(s,encoding='utf-8')
print('Hospital workspace structure redesigned')
